import { GeoGlobe, type GlobeConnection, type GlobeLocation } from "@/components/lumesec/geo-globe";

const regions: GlobeLocation[] = [
  { id: "us-east", label: "us-east", lat: 39.04, lon: -77.49 },
  { id: "eu-central", label: "eu-central", lat: 50.11, lon: 8.68 },
  { id: "ap-southeast", label: "ap-southeast", lat: 1.35, lon: 103.82 },
];

export function Example({ recent }: { recent: GlobeConnection[] }) {
  return <GeoGlobe locations={regions} connections={recent} defaultValue="eu-central" />;
}
